// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.applockimport android.app.Activityimport android.view.WindowManagerimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Flag Secure Manager (Module 12, Pillar 5). * * Strategy §12.5 — applies [WindowManager.LayoutParams.FLAG_SECURE] per-screen. * * ## What FLAG_SECURE does * *   1. **Prevents screenshots** — `MediaProjection` and the system screenshot *      shortcut (Power + Volume Down) show a black screen instead. *   2. **Prevents screen recording** — same as above for screen recorders. *   3. **Hides content in Recents** — the thumbnail in the recent apps *      list is blanked out. *   4. **Prevents content mirroring** — content is not shown on external *      displays (e.g., Cast, DeX). * * ## Real Android APIs * * - `WindowManager.LayoutParams.FLAG_SECURE` — the actual flag added to *   the window's layout params via `window.setFlags(FLAG_SECURE, FLAG_SECURE)`. * - `Activity.getWindow()` — the window to apply the flag to. * * ## Usage * * Activities call [applyToActivity] in `onCreate` (after `setContentView`): * * ```kotlin * class SettingsActivity : FragmentActivity() { *     @Inject lateinit var flagSecureManager: FlagSecureManager * *     override fun onCreate(savedInstanceState: Bundle?) { *         super.onCreate(savedInstanceState) *         setContentView(R.layout.activity_settings) *         flagSecureManager.applyToActivity(this, ScreenType.SETTINGS) *     } * } * ``` * * The manager reads the user's [ScreenSecurityLevel] preference and decides * whether to apply FLAG_SECURE. This centralizes the policy so individual * activities don't have to. * * @see ScreenType * @see ScreenSecurityLevel */@Singletonclass FlagSecureManager @Inject constructor() {    /**     * The current screen security level. Defaults to STANDARD.     *     * In a production build, this would be backed by a Flow from     * [com.roshan.persona.datastore.NousPreferences] (a new     * `screenSecurityLevel` preference). For now, the field is mutable     * and updated by the Settings UI via [setLevel].     */    @Volatile    private var level: ScreenSecurityLevel = ScreenSecurityLevel.STANDARD    /**     * Whether "hide preview in recents" is enabled. Default true (paranoid).     *     * When true, the CHAT screen gets FLAG_SECURE even at STANDARD level.     * When false, CHAT is unsecured (allows screenshots).     */    @Volatile    private var hidePreviewInRecents: Boolean = true    /**     * Apply (or remove) FLAG_SECURE on the given activity's window based     * on the [ScreenType] and the current [ScreenSecurityLevel].     *     * @param activity the activity whose window to secure.     * @param screenType which screen this is (drives the default policy).     */    fun applyToActivity(activity: Activity, screenType: ScreenType) {        val shouldSecure = shouldSecure(screenType)        try {            if (shouldSecure) {                activity.window.setFlags(                    WindowManager.LayoutParams.FLAG_SECURE,                    WindowManager.LayoutParams.FLAG_SECURE,                )            } else {                activity.window.clearFlags(WindowManager.LayoutParams.FLAG_SECURE)            }        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "Failed to apply FLAG_SECURE")        }    }    /**     * Compute whether a screen should be FLAG_SECURE based on the current     * [ScreenSecurityLevel] and the [ScreenType].     *     * Policy:     *   - **STRICT**: always true (all screens secured).     *   - **NONE**: always false (no screens secured).     *   - **STANDARD**:     *     - SETTINGS, CREDENTIAL_VAULT, BACKUP → always true (sensitive).     *     - MEMORY → true by default (may contain private content).     *     - CHAT → true if [hidePreviewInRecents]; false otherwise.     *     - DEFAULT, ONBOARDING → false.     */    fun shouldSecure(screenType: ScreenType): Boolean = when (level) {        ScreenSecurityLevel.STRICT -> true        ScreenSecurityLevel.NONE -> false        ScreenSecurityLevel.STANDARD -> when (screenType) {            ScreenType.SETTINGS,            ScreenType.CREDENTIAL_VAULT,            ScreenType.BACKUP -> true            ScreenType.MEMORY -> true            ScreenType.CHAT -> hidePreviewInRecents            ScreenType.ONBOARDING,            ScreenType.DEFAULT -> false        }    }    /**     * Update the global [ScreenSecurityLevel]. Affects all future     * [applyToActivity] calls; existing windows are NOT retroactively     * updated (activities must re-apply on next onResume).     */    fun setLevel(newLevel: ScreenSecurityLevel) {        level = newLevel        Timber.tag("NOUS.Security").i("Screen security level set to %s", newLevel)    }    /**     * Update the "hide preview in recents" preference (affects CHAT only).     */    fun setHidePreviewInRecents(hide: Boolean) {        hidePreviewInRecents = hide        Timber.tag("NOUS.Security").i("Hide preview in recents: %b", hide)    }    /** Read the current [ScreenSecurityLevel]. */    fun getLevel(): ScreenSecurityLevel = level    /** Read the current "hide preview in recents" preference. */    fun isHidePreviewInRecents(): Boolean = hidePreviewInRecents}
